// Input validation for the lead intake webhook.
// Runs in an n8n Code node (mode: runOnceForAllItems).
const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const str = (v) => (typeof v === 'string' ? v.trim() : '');
const errors = [];

const eventId = str(body.event_id);
const email = str(body.email).toLowerCase();
const name = str(body.name).slice(0, 200);
const source = str(body.source).slice(0, 60);

if (!eventId || eventId.length > 100) errors.push('event_id is required (1-100 chars)');
if (email.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email is missing or invalid');
if (!name) errors.push('name is required');
if (!source) errors.push('source is required');

if (errors.length > 0) {
  return [{ json: { valid: false, errors, event_id: eventId || null } }];
}

return [{
  json: {
    valid: true,
    event_id: eventId,
    idempotency_key: 'lead:' + eventId,
    payload: { email, name, source, event_id: eventId },
  },
}];

// Looks up the idempotency key in the workflow's static data.
// Keys are stored only after the CRM confirmed success (see record_outcome.js).
const store = $getWorkflowStaticData('global');
store.done = store.done || {};
const item = $input.first().json;
const duplicate = Object.prototype.hasOwnProperty.call(store.done, item.idempotency_key);
return [{ json: { ...item, duplicate } }];

// Calls the CRM with bounded retries, exponential backoff with jitter, and Retry-After support.
// The same Idempotency-Key is sent on every attempt, so a retry cannot create a second contact.
// Secrets come from n8n environment variables (CRM_API_KEY, CRM_BASE_URL), never from the node.
const MAX_ATTEMPTS = 4;
const BASE_MS = 500;
const CAP_MS = 8000;
const RETRYABLE = new Set([408, 425, 429, 500, 502, 503, 504]);

const item = $input.first().json;
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const url = $env.CRM_BASE_URL + '/v1/contacts';
const started = Date.now();

let attempts = 0;
let status = null;
let errorClass = null;

while (attempts < MAX_ATTEMPTS) {
  attempts += 1;
  errorClass = null;
  let delayFromHeader = null;
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url,
      headers: {
        Authorization: 'Bearer ' + $env.CRM_API_KEY,
        'Content-Type': 'application/json',
        'Idempotency-Key': item.idempotency_key,
      },
      body: item.payload,
      json: true,
      ignoreHttpStatusErrors: true,
      returnFullResponse: true,
      timeout: 10000,
    });
    status = res.statusCode;
    if (status >= 200 && status < 300) {
      return [{ json: { ...item, ok: true, crm_status: status, errorClass: null, attempts, duration_ms: Date.now() - started } }];
    }
    // 400, 401, 403, 404, 422: retrying the same payload will not help, stop now.
    if (!RETRYABLE.has(status)) break;
    const ra = res.headers && res.headers['retry-after'];
    if (ra !== undefined && ra !== '' && !isNaN(Number(ra))) delayFromHeader = Number(ra) * 1000;
  } catch (err) {
    status = null;
    errorClass = 'network';
  }
  if (attempts < MAX_ATTEMPTS) {
    const backoff = Math.min(CAP_MS, BASE_MS * 2 ** (attempts - 1)) + Math.floor(Math.random() * 250);
    await sleep(delayFromHeader !== null ? Math.min(CAP_MS, delayFromHeader) : backoff);
  }
}

if (!errorClass) {
  errorClass = status !== null && RETRYABLE.has(status) ? 'retries_exhausted' : 'http_' + status;
}
return [{ json: { ...item, ok: false, crm_status: status, errorClass, attempts, duration_ms: Date.now() - started } }];

// Stores successful keys (so a later duplicate is ignored) and prints one redacted log line.
// Failed keys are NOT stored, so the sender's retry is allowed to succeed later.
// The log never contains the API key, headers, or the full email address.
const MAX_KEYS = 5000;
const store = $getWorkflowStaticData('global');
store.done = store.done || {};
const item = $input.first().json;

if (item.ok) {
  store.done[item.idempotency_key] = Date.now();
  const keys = Object.keys(store.done);
  if (keys.length > MAX_KEYS) {
    keys
      .sort((a, b) => store.done[a] - store.done[b])
      .slice(0, keys.length - MAX_KEYS)
      .forEach((k) => delete store.done[k]);
  }
}

const maskEmail = (e) => {
  if (typeof e !== 'string' || !e.includes('@')) return null;
  const [user, domain] = e.split('@');
  return user.slice(0, 1) + '***@' + domain;
};

const log = {
  event: 'lead_intake',
  idempotency_key: item.idempotency_key,
  ok: item.ok,
  crm_status: item.crm_status,
  error_class: item.errorClass,
  attempts: item.attempts,
  duration_ms: item.duration_ms,
  email: maskEmail(item.payload && item.payload.email),
};
console.log(JSON.stringify(log));
return [{ json: { ...item, log } }];
